  if(selected==null&&java.util.Arrays.asList("play","pause","next","previous").contains(op)){
   Intent media=new Intent("android.intent.action.MEDIA_BUTTON").setPackage(args[1]);java.util.List<android.content.pm.ResolveInfo> receivers=context.getPackageManager().queryBroadcastReceivers(media,0);if(receivers.isEmpty())throw new Exception("Плеер не принимает команды в фоне. Откройте его на станции");android.content.pm.ActivityInfo receiver=receivers.get(0).activityInfo;media.setComponent(new ComponentName(receiver.packageName,receiver.name));int code="play".equals(op)?126:"pause".equals(op)?127:"next".equals(op)?87:88;long now=android.os.SystemClock.uptimeMillis();for(int action:new int[]{0,1}){media.putExtra(Intent.EXTRA_KEY_EVENT,new android.view.KeyEvent(now,now,action,code,0));context.sendBroadcast(media);}o.put("ok",true);o.put("dispatched",true);return o;
  }
  if(selected==null)throw new Exception("Откройте выбранный плеер на станции");PlaybackState state=selected.getPlaybackState();long actions=state==null?0:state.getActions();o.put("actions",actions);
  if("search".equals(op)){if((actions&PlaybackState.ACTION_PLAY_FROM_SEARCH)==0&&!"com.spotify.tv.android".equals(args[1]))throw new Exception("Плеер не поддерживает запуск по поисковому запросу");android.os.Bundle extras=new android.os.Bundle();extras.putString("android.intent.extra.user_query_language","ru-RU");extras.putBoolean("android.intent.extra.voice_query",true);selected.getTransportControls().playFromSearch(query,extras);o.put("accepted",true);}
  else if("uri".equals(op)){selected.getTransportControls().playFromUri(android.net.Uri.parse(query),new android.os.Bundle());o.put("accepted",true);}
  else if("seek".equals(op)||"seek-by".equals(op)){if((actions&PlaybackState.ACTION_SEEK_TO)==0)throw new Exception("Этот плеер не поддерживает перемотку через медиасессию");long position=Long.parseLong(query);if("seek-by".equals(op)){long now=state==null?0:state.getPosition();if(state!=null&&state.getState()==PlaybackState.STATE_PLAYING)now+=(long)((android.os.SystemClock.elapsedRealtime()-state.getLastPositionUpdateTime())*state.getPlaybackSpeed());position+=now;}MediaMetadata metadata=selected.getMetadata();long duration=metadata==null?0:metadata.getLong(MediaMetadata.METADATA_KEY_DURATION);position=Math.max(0,Math.min(duration>0?duration:86400000,position));selected.getTransportControls().seekTo(position);}
  else if("shuffle".equals(op)){if((actions&2097152L)==0)throw new Exception("Этот плеер не поддерживает изменение случайного порядка");android.os.Bundle options=new android.os.Bundle();options.putInt("android.support.v4.media.session.action.ARGUMENT_SHUFFLE_MODE",Integer.parseInt(query));selected.getTransportControls().sendCustomAction("android.support.v4.media.session.action.SET_SHUFFLE_MODE",options);}
